36	/**
37	 * Unified realtime session. `provider.engine` selects the engine:
38	 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
39	 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
40	 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
41	 *   - "openai" → real gpt-realtime-2 voice via WebRTC (useOpenaiSession)
42	 * All expose the same `SessionApi` so the UI is provider-agnostic.
43	 *
44	 * `useXaiSession` and `useOpenaiSession` share one interface, so the dispatcher
45	 * picks whichever is active as `custom` and routes every control through it.
46	 *
47	 * All real-engine hooks (`useConversation`, `useXaiSession`, `useOpenaiSession`)
48	 * are called unconditionally (rules of hooks) and stay inert until their engine
49	 * is selected and started.
50	 */
51	export function useRealtimeSession({
52	  provider,
53	  persona,
54	  lmModelId,
55	  voiceBargeIn,
56	}: {
57	  provider: Provider;
58	  persona?: Persona;
59	  /** Cascade-only: overrides the catalog default LM model (from the Providers picker). */
60	  lmModelId?: string;
61	  /** OpenAI-only: let user speech interrupt the agent (settings INTERRUPTIONS toggle). */
62	  voiceBargeIn?: boolean;
63	}): SessionApi {
64	  const engine = provider.engine;
65	  const isReal = !!engine;
66	
67	  const [callState, setCallState] = useState<CallState>(isReal ? "idle" : "listening");
68	  const [turns, setTurns] = useState<SessionTurn[]>(isReal ? [] : SCRIPT_TURNS);
69	  const [caption, setCaption] = useState<string>(
70	    isReal ? "press CALL to begin" : mockCaption("listening"),
71	  );
72	  const [muted, setMuted] = useState(false);
73	  const [elapsed, setElapsed] = useState(0);
74	
75	  const stateRef = useRef(callState);
76	  stateRef.current = callState;
77	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
78	  const clearTimers = () => {
79	    timers.current.forEach(clearTimeout);
80	    timers.current = [];
81	  };
82	
83	  // ── ElevenLabs real conversation ──────────────────────────────────────────
84	  const realPhase = useRef<"idle" | "active" | "ended">("idle");
85	  const conversation = useConversation({
86	    micMuted: muted,
87	    onMessage: (msg: { source?: string; message?: string }) => {
88	      const who = msg.source === "user" ? "user" : "agent";
89	      const text = msg.message ?? "";
90	      if (!text) return;
91	      setTurns((prev) => [...prev, { id: `r${prev.length}`, who, text }]);
92	      setCaption(text);
93	    },
94	    onError: () => {
95	      realPhase.current = "ended";
96	      setCallState("ended");
97	      setCaption("— connection error —");
98	    },
99	  });
100	
101	  const { status, mode, isSpeaking, startSession, endSession } = conversation;
102	
103	  // ── Custom real engines (own WebSocket / WebRTC, shared interface) ─────────
104	  const xai = useXaiSession(engine === "xai", persona);
105	  const openai = useOpenaiSession(engine === "openai", persona, voiceBargeIn ?? false);
106	  const cascade = useCascadeSession(engine === "cascade", persona, lmModelId);
107	  // Whichever custom engine is active owns the session; null ⇒ ElevenLabs/mock.
108	  const custom =
109	    engine === "xai" ? xai : engine === "openai" ? openai : engine === "cascade" ? cascade : null;
110	
111	  // The active call state comes from whichever engine owns the session.
112	  const activeCallState: CallState = custom ? custom.callState : callState;
113	
114	  // Derive real CallState from the conversation status/mode (ElevenLabs only).
115	  useEffect(() => {
116	    if (engine !== "elevenlabs" || realPhase.current === "idle") return;
117	    if (realPhase.current === "ended") {
118	      setCallState("ended");
119	      return;
120	    }
121	    if (status === "connecting") setCallState("connecting");
122	    else if (status === "error") setCallState("ended");
123	    else if (status === "disconnected") setCallState("ended");
124	    else if (status === "connected") {
125	      setCallState(mode === "speaking" || isSpeaking ? "speaking" : "listening");
126	      setCaption((c) => (c === "establishing session…" ? "listening…" : c));
127	    }
128	  }, [engine, status, mode, isSpeaking]);
129	
130	  // ── Mock lifecycle ──────────────────────────────────────────────────────────
131	  // First-load drift: listening → speaking after 5s (matches the prototype).
132	  useEffect(() => {
133	    if (isReal) return;
134	    if (callState !== "listening") return;
135	    const t = setTimeout(() => setCallState("speaking"), 5000);
136	    return () => clearTimeout(t);
137	    // eslint-disable-next-line react-hooks/exhaustive-deps
138	  }, [isReal]);
139	
140	  // Caption sync for the mock engine.
141	  useEffect(() => {
142	    if (isReal) return;
143	    setCaption(mockCaption(callState));
144	  }, [isReal, callState]);
145	
146	  // Elapsed ticker (all engines) — keyed off whichever engine owns the call.
147	  useEffect(() => {
148	    if (activeCallState === "idle" || activeCallState === "ended") {
149	      setElapsed(0);
150	      return;
151	    }
152	    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
153	    return () => clearInterval(t);
154	  }, [activeCallState]);
155	
156	  // Push mute into the active real engine. ElevenLabs only accepts setMuted once
157	  // connected (it throws "No active conversation" before startSession()); xAI
158	  // gates its own mic send, so it's always safe.
159	  useEffect(() => {
160	    if (engine === "elevenlabs" && status === "connected") conversation.setMuted(muted);
161	    else if (custom) custom.setMuted(muted);
162	    // eslint-disable-next-line react-hooks/exhaustive-deps
163	  }, [muted, engine, status]);
164	
165	  // Reset to the active engine's initial state when the engine changes. End any
166	  // live ElevenLabs session we're navigating away from (xAI tears itself down
167	  // via its own `active` effect).
168	  useEffect(() => {
169	    clearTimers();
170	    try {
171	      if (realPhase.current === "active") endSession();
172	    } catch {
173	      // no active ElevenLabs session
174	    }
175	    realPhase.current = "idle";
176	    if (isReal) {
177	      setCallState("idle");
178	      setTurns([]);
179	      setCaption("press CALL to begin");
180	    } else {
181	      setCallState("listening");
182	      setTurns(SCRIPT_TURNS);
183	      setCaption(mockCaption("listening"));
184	    }
185	    // eslint-disable-next-line react-hooks/exhaustive-deps
186	  }, [engine]);
187	
188	  useEffect(() => () => clearTimers(), []);
189	
190	  // ── Controls ────────────────────────────────────────────────────────────────
191	  const start = useCallback(() => {
192	    if (custom) {
193	      custom.start();
194	      return;
195	    }
196	    if (engine === "elevenlabs") {
197	      if (callState === "idle" || callState === "ended") {
198	        const agentId = process.env.NEXT_PUBLIC_ELEVENLABS_AGENT_ID;
199	        if (!agentId) {
200	          setCaption("— set NEXT_PUBLIC_ELEVENLABS_AGENT_ID —");
201	          return;
202	        }
203	        realPhase.current = "active";
204	        setTurns([]);
205	        setCallState("connecting");
206	        setCaption("establishing session…");
207	        startSession({ agentId, connectionType: "webrtc" } as Parameters<typeof startSession>[0]);
208	      } else {
209	        realPhase.current = "ended";
210	        endSession();
211	        setCallState("ended");
212	      }
213	      return;
214	    }
215	    // Mock
216	    clearTimers();
217	    if (callState === "idle" || callState === "ended") {
218	      setTurns(SCRIPT_TURNS);
219	      setCallState("connecting");
220	      timers.current.push(setTimeout(() => setCallState("listening"), 1400));
221	      timers.current.push(setTimeout(() => setCallState("speaking"), 3600));
222	    } else {
223	      setCallState("ended");
224	    }
225	  }, [engine, custom, callState, startSession, endSession]);
226	
227	  const hangup = useCallback(() => {
228	    if (custom) {
229	      custom.stop();
230	      return;
231	    }
232	    if (engine === "elevenlabs") {
233	      realPhase.current = "ended";
234	      endSession();
235	    } else {
236	      clearTimers();
237	    }
238	    setCallState("ended");
239	  }, [engine, custom, endSession]);
240	
241	  const interrupt = useCallback(() => {
242	    if (custom) {
243	      custom.interrupt();
244	      return;
245	    }
246	    if (stateRef.current !== "speaking") return;
247	    if (engine === "elevenlabs") {
248	      conversation.sendUserActivity();
249	      setCallState("interrupted");
250	      return;
251	    }
252	    clearTimers();
253	    setCallState("interrupted");
254	    timers.current.push(setTimeout(() => setCallState("listening"), 900));
255	  }, [engine, custom, conversation]);
256	
257	  const toggleMute = useCallback(() => setMuted((m) => !m), []);
258	
259	  // Manual end-of-turn — only the half-duplex cascade STT exposes one.
260	  const canSendTurn = engine === "cascade";
261	  const sendTurn = useCallback(() => {
262	    if (engine === "cascade") cascade.sendTurn();
263	  }, [engine, cascade]);
264	
265	  // ── Volumes for the orb ───────────────────────────────────────────────────
266	  const getInputVolume = useCallback(() => {
267	    if (engine === "elevenlabs") {
268	      // Throws before startSession(); fall back to silence until connected.
269	      try {
270	        return conversation.getInputVolume();
271	      } catch {
272	        return 0;
273	      }
274	    }
275	    const s = stateRef.current;
276	    if (s === "listening" || s === "interrupted") {
277	      return 0.25 + 0.4 * Math.abs(Math.sin(performance.now() / 180));
278	    }
279	    return 0.04;
280	  }, [engine, conversation]);
281	
282	  const getOutputVolume = useCallback(() => {
283	    if (engine === "elevenlabs") {
284	      try {
285	        return conversation.getOutputVolume();
286	      } catch {
287	        return 0;
288	      }
289	    }
290	    const s = stateRef.current;
291	    if (s === "speaking") {
292	      return 0.4 + 0.45 * Math.abs(Math.sin(performance.now() / 140));
293	    }
294	    return 0.04;
295	  }, [engine, conversation]);
296	
297	  return useMemo<SessionApi>(
298	    () => ({
299	      callState: activeCallState,
300	      turns: custom ? custom.turns : turns,
301	      caption: custom ? custom.caption : caption,
302	      muted,
303	      elapsed,
304	      isReal,
305	      toggleMute,
306	      start,
307	      hangup,
308	      interrupt,
309	      sendTurn,
310	      canSendTurn,
311	      getInputVolume: custom ? custom.getInputVolume : getInputVolume,
312	      getOutputVolume: custom ? custom.getOutputVolume : getOutputVolume,
313	    }),
314	    [
315	      activeCallState,
316	      custom,
317	      turns,
318	      caption,
319	      muted,
320	      elapsed,
321	      isReal,
322	      toggleMute,
323	      start,
324	      hangup,
325	      interrupt,
326	      sendTurn,
327	      canSendTurn,
328	      getInputVolume,
329	      getOutputVolume,
330	    ],
331	  );
332	}
