// Headless probe of the fal PersonaPlex realtime WS — mirrors use-fal-session.
// Mints a JWT via the dev server, streams silence chunks at realtime cadence,
// and reports what the server sends back (frame types, audio volume, text).

const CHUNK_SAMPLES = 1920; // 80ms @ 24kHz
const RUN_MS = 8000;

