);
ws.binaryType = "arraybuffer";

let audioMsgs = 0;
let audioSamples = 0;
let voicedMsgs = 0;
let firstAudioAt = -1;
let textBuf = "";
const otherMsgs: string[] = [];
const t0 = Date.now();

