  const keys = Object.keys(msg).filter((k) => !["audio", "text", "request_id"].includes(k));
  if (keys.length) otherMsgs.push(JSON.stringify(Object.fromEntries(keys.map((k) => [k, msg[k]]))));
};

ws.onerror = () => console.log("ws error");
ws.onclose = (ev) => {
  console.log(`closed code=${ev.code} @${Date.now() - t0}ms`);
  console.log(
