// Probe v3: real speech input as raw msgpack bytes — does the model HEAR us?
// Streams 3s of silence (greeting window), then bench-input.wav (24kHz PCM16
// speech), then silence; checks the response text/audio react to the speech.
import { decode, encode } from "@msgpack/msgpack";

const CHUNK_SAMPLES = 1920; // 80ms @ 24kHz
const RUN_MS = 24000;
const WAV = "/Users/jessearmand/Develop/personaplex-mlx/scratchpad/bench-input.wav";

const tokRes = await fetch("http://localhost:3000/api/fal/token", { method: "POST" });
const { token } = (await tokRes.json()) as { token?: string };
if (!token) throw new Error("no token");

// Raw PCM16 from the WAV (44-byte canonical header).
const wavBytes = new Uint8Array(await Bun.file(WAV).arrayBuffer()).slice(44);
const silent = new Uint8Array(CHUNK_SAMPLES * 2);
const config = {
  prompt: "You are a friendly, engaging conversation partner named Tsubaki.",
  voice: "NATF2",
  temperature_text: 0.7,
  temperature_audio: 0.8,
  top_k_text: 25,
  top_k_audio: 250,
};

const ws = new WebSocket(
  `wss://fal.run/fal-ai/personaplex/realtime?fal_jwt_token=REDACTED,
);
ws.binaryType = "arraybuffer";

let audioSamples = 0;
let voicedMsgs = 0;
let textBuf = "";
const t0 = Date.now();
let wavOffset = 0;

ws.onopen = () => {
  console.log(`open @${Date.now() - t0}ms — silence 3s → speech 10.6s → silence`);
  ws.send(encode({ ...config, audio: silent })); // config kick, raw-bytes audio
  const iv = setInterval(() => {
    if (ws.readyState !== WebSocket.OPEN) return;
    const el = Date.now() - t0;
    let chunk: Uint8Array;
    if (el < 3000 || wavOffset >= wavBytes.length) chunk = silent;
    else {
      chunk = wavBytes.slice(wavOffset, wavOffset + CHUNK_SAMPLES * 2);
      wavOffset += CHUNK_SAMPLES * 2;
    }
    ws.send(encode({ ...config, audio: chunk }));
  }, 80);
  setTimeout(() => {
    clearInterval(iv);
    ws.close();
  }, RUN_MS);
};

ws.onmessage = (ev) => {
  if (typeof ev.data === "string") return;
  let msg: Record<string, unknown>;
  try {
    msg = decode(new Uint8Array(ev.data as ArrayBuffer)) as Record<string, unknown>;
  } catch {
    return;
  }
  const audio = msg.audio;
  if (audio instanceof Uint8Array && audio.length > 0) {
    const n = audio.length / 2;
    audioSamples += n;
    const dv = new DataView(audio.buffer, audio.byteOffset, audio.byteLength);
    let sum = 0;
    for (let i = 0; i < n; i++) sum += (dv.getInt16(i * 2, true) / 32768) ** 2;
    if (Math.sqrt(sum / n) > 0.01) voicedMsgs++;
  }
  if (typeof msg.text === "string" && msg.text.length > 0) textBuf += msg.text;
};

ws.onclose = (ev) => {
  console.log(`closed code=${ev.code} @${Date.now() - t0}ms`);
  console.log(`audio: ${(audioSamples / 24000).toFixed(2)}s total, voiced msgs=${voicedMsgs}`);
  console.log("agent text:", JSON.stringify(textBuf));
  process.exit(0);
};
ws.onerror = () => console.log("ws error");

