    async def handle_chat(self, request):
        ws = web.WebSocketResponse()
        await ws.prepare(request)

        voice_name = request.query.get("voice_prompt", "")
        text_prompt = request.query.get("text_prompt", "")
        seed = int(request.query.get("seed", self.args.seed))
        if voice_name == "":
            voice_name = self.args.voice_prompt or self.args.voice
        if text_prompt == "":
            text_prompt = self.args.text_prompt

        voice_path = resolve_voice_prompt(
            voice=None,
            voice_prompt=voice_name,
            voice_prompt_dir=self.args.voice_prompt_dir,
        )

        input_queue: queue.Queue[np.ndarray] = queue.Queue()
        text_queue: queue.Queue[str] = queue.Queue()
        audio_tokenizer = rustymimi.StreamTokenizer(self.mimi_file, num_codebooks=8)  # type: ignore
        opus_writer = sphn.OpusStreamWriter(SAMPLE_RATE)
        opus_reader = sphn.OpusStreamReader(SAMPLE_RATE)
        output_pacer = OutboundAudioPacer(SAMPLE_RATE)
        greeting_gate = (
            GreetingGate(
                SAMPLE_RATE,
                voice_rms=self.args.greeting_gate_rms,
                end_silence_s=self.args.greeting_gate_end_ms / 1000,
                max_s=self.args.greeting_gate_max_ms / 1000,
            )
            if self.args.greeting_gate
            else None
        )
        close = False

        async def recv_loop():
            nonlocal close
            all_pcm_data = None
            try:
                async for message in ws:
                    if message.type in (
                        aiohttp.WSMsgType.ERROR,
                        aiohttp.WSMsgType.CLOSE,
                        aiohttp.WSMsgType.CLOSED,
                    ):
                        break
                    if message.type != aiohttp.WSMsgType.BINARY:
                        continue
                    payload = message.data
                    if not isinstance(payload, bytes) or len(payload) == 0:
                        continue
                    if payload[0] != 1:
                        continue
                    pcm = opus_reader.append_bytes(payload[1:])
                    if pcm.shape[-1] == 0:
                        continue
                    if all_pcm_data is None:
                        all_pcm_data = pcm
                    else:
                        all_pcm_data = np.concatenate((all_pcm_data, pcm))
                    while all_pcm_data.shape[-1] >= FRAME_SIZE:
                        chunk = all_pcm_data[:FRAME_SIZE]
                        all_pcm_data = all_pcm_data[FRAME_SIZE:]
                        # Mic-gate the opening greeting: feed the model silence
                        # until it finishes greeting, so it doesn't yield its turn
                        # on ambient mic noise and chop its own greeting.
                        if greeting_gate is not None and greeting_gate.is_muted():
                            input_queue.put_nowait(np.zeros(FRAME_SIZE, dtype=np.float32))
                        else:
                            input_queue.put_nowait(chunk.astype(np.float32))
            finally:
                close = True

        async def encode_loop():
            while True:
                if close:
                    return
                await asyncio.sleep(0.001)
                try:
                    pcm = input_queue.get(block=False)
                except queue.Empty:
                    continue
                audio_tokenizer.encode(pcm)

        async def model_loop():
            while True:
                if close:
                    return
                tokens = audio_tokenizer.get_encoded()
                if tokens is None:
                    await asyncio.sleep(0.001)
                    continue
                model_input = mx.array(tokens).transpose(1, 0)[:, : self.gen.user_codebooks]
                model_input = model_input[:, :, None]
                text_token = REDACTED
                if text_token is not None:
                    text_value = int(text_token[0].item())
                    if text_value not in (0, 3):
                        piece = self.text_tokenizer.id_to_piece(text_value)  # type: ignore
                        text_queue.put_nowait(piece.replace("▁", " "))
                audio_tokens = self.gen.last_audio_tokens()
                if audio_tokens is not None:
                    audio_tokenizer.decode(np.array(audio_tokens).astype(np.uint32))
                # Yield between steps so send_loop can pace/flush output. Without
                # this, a startup backlog of encoded frames is consumed in a tight
                # run of ~64ms blocking MLX steps, starving send_loop for ~0.5s and
                # underrunning the browser jitter buffer (greeting crackle).
                await asyncio.sleep(0)

        async def send_loop():
            nonlocal close
            while True:
                if close:
                    return
                await asyncio.sleep(0.001)
                if ws.closed:
                    close = True
                    return
                decoded = audio_tokenizer.get_decoded()
                if decoded is not None:
                    if greeting_gate is not None:
                        greeting_gate.observe_output(decoded)
                    await output_pacer.wait_for_pcm(decoded)
                    msg = opus_writer.append_pcm(decoded)
                    if len(msg) > 0:
                        try:
                            await ws.send_bytes(b"\x01" + msg)
                        except aiohttp.ClientConnectionResetError:
                            close = True
                            return
                try:
                    text = text_queue.get(block=False)
                    try:
                        await ws.send_bytes(b"\x02" + text.encode("utf-8"))
                    except aiohttp.ClientConnectionResetError:
                        close = True
                        return
                except queue.Empty:
                    pass

        async with self.lock:
            seed_all(seed)
            self.gen.reset_streaming()
            self.gen.load_voice_prompt_embeddings(voice_path)
            if text_prompt:
                self.gen.text_prompt_tokens = self.text_tokenizer.encode(wrap_with_system_tags(text_prompt))  # type: ignore
            else:
                self.gen.text_prompt_tokens = None
            self.gen.step_system_prompts()
            await ws.send_bytes(b"\x00")
            await asyncio.gather(recv_loop(), encode_loop(), model_loop(), send_loop())
        return ws


def get_static_path(static: Optional[str]) -> Optional[str]:
    if static is None:
        log("info", "retrieving static content")
        dist_tgz = hf_hub_download("nvidia/personaplex-7b-v1", "dist.tgz")
        dist_tgz_path = Path(dist_tgz)
        dist = dist_tgz_path.parent / "dist"
        if not dist.exists():
            with tarfile.open(dist_tgz_path, "r:gz") as tar:
                tar.extractall(path=dist_tgz_path.parent)
        return str(dist)
    if static == "none":
        return None
    return static


def add_patched_static_routes(app: web.Application, static_path: str) -> None:
    assets_dir = Path(static_path) / "assets"
    if not assets_dir.exists():
        return

    for asset_path in assets_dir.glob("audio-processor*.js"):

        async def handle_audio_processor(
            _request: web.Request,
            path: Path = asset_path,
        ) -> web.Response:
            return javascript_response(patch_moshi_processor_js(path.read_text()))

        app.router.add_get(f"/assets/{asset_path.name}", handle_audio_processor)

    for asset_path in assets_dir.glob("index*.js"):
        source = asset_path.read_text()
        if "moshiProcessorUrl" not in source:
            continue

