(() => {
  const ctx = window.__caps.find(c => c.__samples && c.__samples.length > 0);
  if (!ctx) return JSON.stringify({error: 'no tapped ctx', caps: window.__caps.length, states: window.__caps.map(c=>c.state)});
  const chunks = ctx.__samples;
  const n = chunks.reduce((a,c)=>a+c.length,0);
  const x = new Float32Array(n);
  let o=0; for (const c of chunks){ x.set(c,o); o+=c.length; }
  // find voiced region
  let first=-1, last=-1;
  for (let i=0;i<n;i+=240){ let s=0; for(let j=i;j<Math.min(i+240,n);j++) s+=x[j]*x[j]; if (Math.sqrt(s/240)>0.01){ if(first<0) first=i; last=i; } }
  if (first<0) return JSON.stringify({error:'all silence', n, state: ctx.state});
  // discontinuities: big sample steps within the voiced region
  let clicks=0, maxStep=0;
  for (let i=first+1;i<=last;i++){ const d=Math.abs(x[i]-x[i-1]); if (d>maxStep) maxStep=d; if (d>0.15) clicks++; }
  // internal silence gaps >= 30ms within voiced region
  let gaps=0, run=0;
  for (let i=first;i<=last;i++){ if (Math.abs(x[i])<1e-4){ run++; } else { if (run>=720) gaps++; run=0; } }
  const t=document.body.textContent; const idx=t.indexOf('LIVE TRANSCRIPT');
  return JSON.stringify({recorded_s:(n/ctx.sampleRate).toFixed(1), voiced_s:((last-first)/ctx.sampleRate).toFixed(1), clicks, maxStep:maxStep.toFixed(3), gaps30ms:gaps, ctxState:ctx.state, transcript:t.slice(idx,idx+150)});
})()

