1	"use client";
2	
3	// Real PersonaPlex full-duplex voice engine over a DIRECT browser→fal.ai
4	// WebSocket (no fal SDK — same direct-socket pattern as useXaiSession).
5	//
6	// Architecture: mint a short-lived JWT at /api/fal/token, then open
7	// `wss://fal.run/fal-ai/personaplex/realtime?fal_jwt_token=REDACTED Transport is
8	// MSGPACK binary frames both ways (verified by probe — the server silently
9	// ignores JSON text frames): we send `{audio: <raw PCM16 bytes>, …config}`
10	// continuously; the server streams back `{audio: <raw PCM16 bytes>, text}`.
11	//
12	// Full-duplex consequences (PersonaPlex is a Moshi-style model that listens
13	// while it speaks — see docs/personaplex-local-inference.md):
14	//   - The model speaks FIRST (trained to open the call) — no greeting bootstrap.
15	//   - There is no server VAD and no turn events: `interrupt()` is a no-op
16	//     (barge-in is native — just talk), and callState is derived from output
17	//     audio activity.
18	//   - No user-side transcript (no ASR anywhere in the path); the agent
19	//     transcript streams as inner-monologue text tokens.
20	//   - The mic is GATED to silence during the opening greeting (GreetingGate),
21	//     and autoGainControl is off, so room noise can't make the model interrupt
22	//     its own greeting. Muting likewise sends zeros — the input timeline must
23	//     stay continuous.
24	//   - Audio is fixed 24kHz PCM16 both ways: the AudioContext is constructed at
25	//     24kHz and the browser resamples mic/speaker at the edges.
26	//
27	// Exposes the same surface as useXaiSession so useRealtimeSession dispatches
28	// uniformly. Must be called unconditionally (rules of hooks); inert until start().
29	
30	import { decode, encode } from "@msgpack/msgpack";
31	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
32	import type { Persona } from "@/lib/data";
33	import { GreetingGate } from "./greeting-gate";
34	import type { CallState, SessionTurn } from "./types";
35	import { createMicCapture, type MicCapture } from "./mic-capture";
36	import { resolveFalAgent } from "./fal-agent";
37	import { ScheduledPlaybackQueue } from "./scheduled-playback";
38	import { calculateRms, float32ToPcm16Bytes, pcm16BytesToFloat32 } from "./xai-audio";
39	
40	const REALTIME_BASE = "wss://fal.run";
41	/** PersonaPlex is fixed at 24kHz mono PCM both directions. */
42	const SAMPLE_RATE = 24000;
43	/** One Mimi frame is 80ms — align mic chunks to the model's step size. */
44	const CHUNK_SAMPLES = 1920;
45	const VOL_GAIN = 3.5;
46	/** Output RMS above this counts as the agent audibly speaking. */
47	const VOICED_RMS = 0.01;
48	/** Keep "speaking" through pad-token gaps shorter than this (halting cadence). */
49	const SPEAKING_HOLD_MS = 700;
50	/** Finalize the agent's transcript turn after this much output quiet. */
51	const TURN_QUIET_MS = 1500;
52	
53	export interface FalSession {
54	  callState: CallState;
55	  turns: SessionTurn[];
56	  caption: string;
57	  start: () => void;
58	  stop: () => void;
59	  interrupt: () => void;
60	  setMuted: (muted: boolean) => void;
61	  getInputVolume: () => number;
62	  getOutputVolume: () => number;
63	}
64	
65	type FalResult = {
66	  type?: string;
67	  status?: string;
68	  error?: string;
69	  reason?: string;
70	  /** Raw PCM16 bytes in msgpack transport (base64 string only in JSON fallback). */
71	  audio?: Uint8Array | string;
72	  text?: string;
73	};
74	
75	export function useFalSession(active: boolean, persona?: Persona): FalSession {
76	  const [callState, setCallState] = useState<CallState>("idle");
77	  const [turns, setTurns] = useState<SessionTurn[]>([]);
78	  const [caption, setCaption] = useState("press CALL to begin");
79	
80	  const wsRef = useRef<WebSocket | null>(null);
81	  const ctxRef = useRef<AudioContext | null>(null);
82	  const streamRef = useRef<MediaStream | null>(null);
83	  const captureRef = useRef<MicCapture | null>(null);
84	  const playbackRef = useRef<ScheduledPlaybackQueue | null>(null);
85	  const gateRef = useRef<GreetingGate | null>(null);
86	
87	  const mutedRef = useRef(false);
88	  const endedRef = useRef(false);
89	  const inputRmsRef = useRef(0);
90	  const turnSeqRef = useRef(0);
91	  const agentTurnIdRef = useRef<string | null>(null);
92	  const agentBufRef = useRef("");
93	  const speakingTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
94	  const turnTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
95	  const stateRef = useRef<CallState>("idle");
96	  stateRef.current = callState;
97	  // Latest selected persona, read at start() time (avoids stale closures).
98	  const personaRef = useRef(persona);
99	  personaRef.current = persona;
100	
101	  const teardown = useCallback(() => {
102	    if (speakingTimerRef.current) {
103	      clearTimeout(speakingTimerRef.current);
104	      speakingTimerRef.current = null;
105	    }
106	    if (turnTimerRef.current) {
107	      clearTimeout(turnTimerRef.current);
108	      turnTimerRef.current = null;
109	    }
110	    if (captureRef.current) {
111	      captureRef.current.stop();
112	      captureRef.current = null;
113	    }
114	    if (streamRef.current) {
115	      streamRef.current.getTracks().forEach((t) => t.stop());
116	      streamRef.current = null;
117	    }
118	    if (playbackRef.current) {
119	      playbackRef.current.stop();
120	      playbackRef.current = null;
121	    }
122	    if (wsRef.current) {
123	      try {
124	        wsRef.current.close();
125	      } catch {
126	        // already closing
127	      }
128	      wsRef.current = null;
129	    }
130	    if (ctxRef.current) {
131	      void ctxRef.current.close();
132	      ctxRef.current = null;
133	    }
134	    gateRef.current = null;
135	    agentTurnIdRef.current = null;
136	    agentBufRef.current = "";
137	    inputRmsRef.current = 0;
138	  }, []);
139	
140	  const start = useCallback(() => {
141	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
142	    endedRef.current = false;
143	    setTurns([]);
144	    setCallState("connecting");
145	    setCaption("establishing session…");
146	
147	    const fail = (msg: string) => {
148	      endedRef.current = true;
149	      teardown();
150	      setCallState("ended");
151	      setCaption(msg);
152	    };
153	
154	    // Everything runs at the model's native 24kHz: the browser resamples the
155	    // mic into this context and the speakers out of it, so no manual SRC.
156	    const ctx = new AudioContext({ sampleRate: SAMPLE_RATE });
157	    ctxRef.current = ctx;
158	    playbackRef.current = new ScheduledPlaybackQueue(ctx);
159	    gateRef.current = new GreetingGate(SAMPLE_RATE);
160	
161	    const agent = resolveFalAgent(personaRef.current?.id);
162	    // Optional-with-default schema: an omitted field means fal's DEFAULT, not
163	    // "keep the previous value" — so the persona config rides on EVERY message.
164	    const config = {
165	      prompt: agent.prompt,
166	      voice: agent.voice,
167	      temperature_text: agent.temperatureText,
168	      temperature_audio: agent.temperatureAudio,
169	      top_k_text: agent.topKText,
170	      top_k_audio: agent.topKAudio,
171	    };
172	
173	    const sendAudio = (audio: Uint8Array) => {
174	      const ws = wsRef.current;
175	      if (ws && ws.readyState === WebSocket.OPEN) ws.send(encode({ ...config, audio }));
176	    };
177	
178	    // Silence for one mic chunk — sent while the greeting gate is closed or the
179	    // user is muted, so the model's input timeline never has holes.
180	    const silentChunk = new Uint8Array(CHUNK_SAMPLES * 2);
181	
182	    // ── mic capture (starts in parallel with the token mint + WS connect) ────
183	    // AudioWorklet-based: chunking runs on the realtime audio thread; the main
184	    // thread only receives finished CHUNK_SAMPLES chunks (see mic-capture.ts).
185	    const startCapture = async () => {
186	      try {
187	        const stream = await navigator.mediaDevices.getUserMedia({
188	          audio: {
189	            channelCount: 1,
190	            echoCancellation: true,
191	            noiseSuppression: true,
192	            // AGC amplifies room tone into "speech" during the greeting window;
193	            // the full-duplex model would yield to it. Keep it off.
194	            autoGainControl: false,
195	          },
196	        });
197	        if (endedRef.current) {
198	          stream.getTracks().forEach((t) => t.stop());
199	          return;
200	        }
201	        streamRef.current = stream;
202	        if (ctx.state === "suspended") await ctx.resume();
203	        const capture = await createMicCapture(ctx, stream, CHUNK_SAMPLES, (chunk) => {
204	          inputRmsRef.current = mutedRef.current ? 0 : calculateRms(chunk);
205	          // Gate closed or muted ⇒ ship silence in the chunk's place.
206	          const gated = !(gateRef.current?.isOpen ?? true) || mutedRef.current;
207	          sendAudio(gated ? silentChunk : float32ToPcm16Bytes(chunk));
208	        });
209	        if (endedRef.current) {
210	          // Hung up while the worklet module loaded.
211	          capture.stop();
212	          return;
213	        }
214	        captureRef.current = capture;
215	      } catch {
216	        fail("— microphone permission denied —");
217	      }
218	    };
219	    void startCapture();
220	
221	    void (async () => {
222	      // Mint the ephemeral JWT server-side (in parallel with capture).
223	      let token: string | null = null;
224	      try {
225	        const res = await fetch("/api/fal/token", { method: "POST" });
226	        const data: unknown = await res.json();
227	        if (!res.ok) {
228	          const err = (data as Record<string, unknown> | null)?.error;
229	          fail(`— ${typeof err === "string" ? err : "token error"} —`);
230	          return;
231	        }
232	        const t = (data as Record<string, unknown> | null)?.token;
233	        if (typeof t === "string") token = t;
234	      } catch {
235	        fail("— could not reach token endpoint —");
236	        return;
237	      }
238	      if (!token) {
239	        fail("— no fal token returned —");
240	        return;
241	      }
242	      if (endedRef.current) return; // hung up (or mic denied) during fetch
243	
244	      // ── transcript helpers (setTurns updaters stay PURE — StrictMode) ──────
245	      const pushAgentDelta = (delta: string) => {
246	        agentBufRef.current += delta;
247	        const text = agentBufRef.current;
248	        setCaption(text);
249	        let id = agentTurnIdRef.current;
250	        if (id) {
251	          const tid = id;
252	          setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
253	        } else {
254	          id = `f${turnSeqRef.current++}`;
255	          agentTurnIdRef.current = id;
256	          const tid = id;
257	          setTurns((prev) => [...prev, { id: tid, who: "agent", text, live: true }]);
258	        }
259	      };
260	      const finalizeAgent = () => {
261	        const id = agentTurnIdRef.current;
262	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
263	        agentTurnIdRef.current = null;
264	        agentBufRef.current = "";
265	      };
266	
267	      const ws = new WebSocket(
268	        `${REALTIME_BASE}/${agent.appId}/realtime?fal_jwt_token=REDACTED,
269	      );
270	      ws.binaryType = "arraybuffer";
271	      wsRef.current = ws;
272	
273	      ws.onopen = () => {
274	        if (endedRef.current) return;
275	        // Kick the session with the persona config; the model greets first,
276	        // so the user is "listening" from the start.
